#include <stdio.h>
#include <string.h>

typedef struct { char name[32]; int votes; } Candidate;

int main(void) {
    Candidate candidates[3];
    for (int i = 0; i < 3; i++) { scanf("%31s", candidates[i].name); candidates[i].votes = 0; }
    int n;
    scanf("%d", &n);
    for (int j = 0; j < n; j++) {
        char name[32]; scanf("%31s", name);
        for (int i = 0; i < 3; i++) if (strcmp(name, candidates[i].name) == 0) { candidates[i].votes++; break; }
    }
    for (int i = 0; i < 3; i++) printf("%s %d\n", candidates[i].name, candidates[i].votes);
    return 0;
}
